using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainEffectPerAmountDiceTierOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/GainEffectPerAmountDiceTier Omen Data")]
public class GainEffectPerAmountDiceTierOmenData : OnStartOfBattleOmenData
{
	[Header("Gain Effect Per Amount Dice Tier Omen Data")]
	[SerializeField]
	private DiceTier diceTier;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			int effectAmount = GetEffectAmount();
			if (effectAmount > 0)
			{
				omenInstance.ActivateOmenFeedback();
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
				{
					OmenLogic.ActivateOmen(BattleAction, effectAmount, null, null);
				});
			}
		};
		AddToStartOfBattleOmenActions();
	}

	private int GetEffectAmount()
	{
		return Mathf.FloorToInt((float)ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false, onlyFromDicePool: true)[diceTier.name] / (float)TriggerAmount) * ActionValue;
	}

	public override string OmenConvertedDescription()
	{
		string startOfBattleLocalizedDescription = GetStartOfBattleLocalizedDescription();
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ApplyEffectForEachXDiePlayerOwn");
		DefaultEffectAction defaultEffectAction = BattleAction as DefaultEffectAction;
		string text = Smart.Format(localizedString, ActionValue, defaultEffectAction.Effect.GetEffectName(), TriggerAmount, diceTier.GetLocalizedDiceTierWithDie());
		string text2 = startOfBattleLocalizedDescription + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + text;
		if (ReferenceSingleton<BattleHandler>.Instance != null)
		{
			string text3 = string.Format("\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPreviewDescription(), BattleAction.GetActionDescription(GetEffectAmount()).RemoveLast());
			text2 += text3;
		}
		return text2;
	}
}
